fun uri =>
  match (System.Uri.unescapeUri uri).dropPrefix? "file://" with
  | none => none
  | some p =>
    have p := p.dropWhile fun c => c != '/';
    if System.Platform.isWindows = true then
      some
        {
          toString :=
            String.map (fun c => if (c == '/') = true then '\\' else c)
              (System.Uri.normalizeDriveExpression✝ p) }
    else some { toString := p.copy }

fun uri =>
  (have decoded := ByteArray.empty;
    let rawBytes := uri.toUTF8;
    let len := rawBytes.size;
    have i := 0;
    let percent := '%'.toNat.toUInt8;
    do
    let __s ←
      forIn { } (decoded, i) fun x __s =>
          have decoded := __s.1;
          let i := __s.2;
          if h : i < len then
            let c := rawBytes[i];
            match
              if h₁ : (c == percent) = true ∧ i + 1 < len then
                have h1 := rawBytes[i + 1];
                match System.Uri.UriEscape.decodeUri.hexDigitToUInt8?✝ h1 with
                | some hd1 =>
                  if h₂ : i + 2 < len then
                    have h2 := rawBytes[i + 2];
                    match System.Uri.UriEscape.decodeUri.hexDigitToUInt8?✝ h2 with
                    | some hd2 => (decoded.push (hd1 * 16 + hd2), i + 3)
                    | x => (((decoded.push c).push h1).push h2, i + 3)
                  else ((decoded.push c).push h1, i + 2)
                | x => ((decoded.push c).push h1, i + 2)
              else (decoded.push c, i + 1) with
            | (decoded, i) => pure (ForInStep.yield (decoded, i))
          else pure (ForInStep.done (decoded, i))
    have decoded : ByteArray := __s.1
    pure (String.fromUTF8! decoded)).run

fun c =>
  have d2 := c / 16;
  have d1 := c % 16;
  (hexDigitRepr d2.toNat ++ hexDigitRepr d1.toNat).toUpper

fun fname =>
  (have uri := fname.normalize.toString;
    have __do_jp := fun __r uri =>
      have uri := String.foldl (fun s c => s ++ System.Uri.UriEscape.uriEscapeAsciiChar c) "" uri;
      have result := if uri.startsWith "/" = true then "file://" ++ uri else "file:///" ++ uri;
      result;
    if System.Platform.isWindows = true then
      have uri := System.Uri.normalizeDriveLetter✝ uri;
      have uri := String.map (fun c => if (c == '\\') = true then '/' else c) uri;
      __do_jp () uri
    else __do_jp () uri).run

